    public static class ProgressIntegrationFixture {
        static void Check(bool value,string why){if(!value)throw new Exception(why);}
        static string Id(){return Guid.NewGuid().ToString("D");}
        sealed class GuardIO:IProgressFileIO {
            readonly ProgressFileIO inner=new ProgressFileIO();internal bool failWrite,held,failVerify,published;
            sealed class Hold:IDisposable{readonly IDisposable inner;readonly GuardIO owner;internal Hold(IDisposable inner,GuardIO owner){this.inner=inner;this.owner=owner;}public void Dispose(){owner.held=false;inner.Dispose();}}
            public byte[] ReadCipher(string p,int max){if(failVerify&&published&&p.EndsWith(".dpapi",StringComparison.Ordinal))throw new IOException("synthetic-lost-binding-ACK");return inner.ReadCipher(p,max);}
            public void WriteNewAndFlush(string p,byte[] b){if(failWrite)throw new IOException("synthetic-full-disk");inner.WriteNewAndFlush(p,b);}
            public void ReplaceWithBackup(string t,string c,string b){inner.ReplaceWithBackup(t,c,b);published=true;}
            public void MoveNew(string t,string c){inner.MoveNew(t,c);published=true;}
            public IDisposable AcquireExclusiveLock(string p){var h=inner.AcquireExclusiveLock(p);held=true;return new Hold(h,this);}
        }
        sealed class Release:IDisposable {readonly Action action;internal Release(Action action){this.action=action;}public void Dispose(){action();}}
        sealed class Actor:IProgressExecutionActor {
            internal readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);internal GuardIO io;internal ProgressExecutionContext context;internal ProgressPreparedRequest prepared;
            internal bool unresolved,foreignLease,decline,allowed=true,failBegin,nullMutation,nullApproval,leaseActive,autoFinish=true,throwAfterClaim,noClaim;internal string journal="empty",writerPath;internal long now=1000;internal int dispatches,begins,approvals,preparedReads,additionalQuantity=3,leaseAcquisitions,leaseReleases;internal Action onApproval,onRevalidate,onBegin;internal TaskCompletionSource<bool> approvalWait,revalidateWait,mutationWait;internal ProgressRunOwnership runLease;internal ProgressRunLease lastOffer;internal bool consumed;internal readonly List<string> trace=new List<string>();
            void OutsideStore(){Check(!io.held,"native callback under progress-file lock");}
            public async Task<IDisposable> AcquireMutationAsync(){OutsideStore();if(nullMutation)return null;if(mutationWait!=null)await mutationWait.Task;Check(await gate.WaitAsync(0),"synthetic-actor-busy");return new Release(()=>gate.Release());}
            public ProgressExecutionContext CaptureContext(){OutsideStore();return ProgressDomain.Clone(context);}
            public ProgressPreparedRequest CapturePrepared(string requestId){OutsideStore();preparedReads++;if(prepared==null||prepared.requestId!=requestId)return null;var p=ProgressDomain.Clone(prepared);p.commandDigest=ProgressDomain.Hash(ProgressDomain.Canonical(new{p.context,p.requestId,p.preparedAt,p.expiresAt,p.craftCount,p.outputPerCraft,p.expectedOutput,additionalQuantity,baselineOwned=7,targetOwned=7+additionalQuantity,allowAutoStop=true}));return p;}
            void NativeReady(ProgressPreparedRequest p){OutsideStore();Check(allowed,"public-gate");Check(!unresolved&&journal=="empty","unresolved");Check(!foreignLease,"foreign-lease");Check(now<p.expiresAt,"expired");Check(ProgressDomain.Canonical(p.context)==ProgressDomain.Canonical(context),"native-context-changed");Check(ProgressDomain.Canonical(p)==ProgressDomain.Canonical(CapturePrepared(p.requestId)),"native-payload-changed");}
            public void ConsumeNonce(ProgressPreparedRequest p){OutsideStore();Check(!consumed&&prepared!=null&&ProgressDomain.Canonical(CapturePrepared(p.requestId))==ProgressDomain.Canonical(p),"native-nonce-invalid");consumed=true;}
            public Task<IDisposable> AcquireExecutionLeaseAsync(ProgressPreparedRequest p){OutsideStore();if(nullApproval)return Task.FromResult<IDisposable>(null);NativeReady(p);Check(!leaseActive,"duplicate-game-lease");var file=new FileStream(writerPath+".game",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);leaseActive=true;leaseAcquisitions++;trace.Add("lease");return Task.FromResult<IDisposable>(new Release(()=>{file.Dispose();leaseActive=false;leaseReleases++;trace.Add("lease-release");}));}
            public async Task<bool> ApproveAsync(ProgressPreparedRequest p){OutsideStore();approvals++;trace.Add("approval");if(onApproval!=null)onApproval();if(approvalWait!=null)await approvalWait.Task;return !decline;}
            public async Task RevalidateAsync(ProgressPreparedRequest p){OutsideStore();if(revalidateWait!=null)await revalidateWait.Task;if(onRevalidate!=null)onRevalidate();NativeReady(p);trace.Add("revalidate");}
            public void RecordBegin(ProgressPreparedRequest p){OutsideStore();if(onBegin!=null)onBegin();NativeReady(p);begins++;journal="inflight";trace.Add("begin");if(failBegin)throw new IOException("synthetic-ACK-loss-after-begin");}
            public void Dispatch(ProgressPreparedRequest p,ProgressRunLease offer){OutsideStore();Check(journal=="inflight"&&consumed,"dispatch-without-journal");lastOffer=offer;if(noClaim)return;runLease=offer.Claim();if(throwAfterClaim)throw new IOException("synthetic-response-lost-after-run-claim");dispatches++;trace.Add("dispatch");if(autoFinish)Terminal();}
