        }
        static void Reject(Action action,string reason){bool rejected=false;try{action();}catch(InvalidOperationException){rejected=true;}Check(rejected,reason);}
        static void Wait(Func<bool> ready,string reason){Check(SpinWait.SpinUntil(ready,15000),reason);}
        sealed class Pump:SynchronizationContext {
            readonly Queue<Action> queue=new Queue<Action>();
            public override void Post(SendOrPostCallback callback,object state){lock(queue)queue.Enqueue(()=>callback(state));}
            internal void Run(Func<Task> body){var old=Current;SetSynchronizationContext(this);try{var task=body();var timer=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted){Action action=null;lock(queue)if(queue.Count>0)action=queue.Dequeue();if(action!=null)action();else Thread.Sleep(1);Check(timer.ElapsedMilliseconds<15000,"single-thread approval pump timed out");}task.GetAwaiter().GetResult();}finally{SetSynchronizationContext(old);}}
        }
        public static string ScriptPath;
        static System.Diagnostics.Process Child(string root,string goal,string mode){var info=new System.Diagnostics.ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+ScriptPath+"\" -Mode worker -Root \""+root+"\" -WorkerGoal "+goal+" -WorkerMode "+mode){UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};return System.Diagnostics.Process.Start(info);}
        static void EndChild(System.Diagnostics.Process p){if(!p.WaitForExit(30000)){p.Kill();throw new Exception("synthetic child timeout");}Check(p.ExitCode==0,"synthetic child failed: "+p.StandardError.ReadToEnd());}
        public static void Worker(string root,string goal,string mode){var s=new DesktopErgonProgressStore(root,"development");var scope=new ProgressScope{environment="development",accountId="synthetic-account",characterId="synthetic-character"};if(mode=="hold"){using(s.AcquireWriter(new ProgressLockOwner())){File.WriteAllText(Path.Combine(root,"held"),"ready");Wait(()=>File.Exists(Path.Combine(root,"release")),"worker release");}Console.WriteLine("released");return;}File.WriteAllText(Path.Combine(root,mode+".ready"),"ready");Wait(()=>File.Exists(Path.Combine(root,"go")),"worker go");Console.WriteLine(s.Commit(new ProgressMutation{kind="SetLifecycle",scope=scope,goalId=goal,lifecycle="paused"},1,Guid.NewGuid()).status);}
        // Synchronous blocking exists only in this console fixture, never on a host/UI path.
        sealed class Calls {
            internal readonly ProgressCoordinator native;
            internal Calls(DesktopErgonProgressStore store,Actor actor,Func<long> clock){native=new ProgressCoordinator(store,actor,clock);}
            internal ProgressExecutionResult CreateGoal(long revision,Guid op){return native.CreateGoalAsync(revision,op).GetAwaiter().GetResult();}
            internal ProgressExecutionResult BindPrepared(string id,long revision,Guid op){return native.BindPreparedAsync(id,revision,op).GetAwaiter().GetResult();}
            internal ProgressExecutionResult Confirm(string id){return native.ConfirmAsync(id).GetAwaiter().GetResult();}
        }
        sealed class Rig {
            internal string root;internal GuardIO io=new GuardIO();internal DesktopErgonProgressStore store;internal Actor actor;internal Calls coordinator;
            internal Rig(string parent){root=Path.Combine(parent,Guid.NewGuid().ToString("N").Substring(0,16));store=new DesktopErgonProgressStore(root,"development",io);actor=new Actor{io=io,writerPath=store.FilePath+".writers.lock",context=new ProgressExecutionContext{scope=new ProgressScope{environment="development",accountId="synthetic-account",characterId="synthetic-character"},goalId=Id(),sourcePlanId="synthetic-plan",action="crafting",displayName="synthetic-sword",targetQuantity=4,sessionId=Id(),documentEpoch=2,contextVersion=3}};actor.prepared=new ProgressPreparedRequest{context=ProgressDomain.Clone(actor.context),requestId=Id(),preparedAt=900,expiresAt=1200,craftCount=3,outputPerCraft=1,expectedOutput=3};coordinator=new Calls(store,actor,()=>actor.now);}
            internal long Revision(){return store.Load(actor.context.scope).revision;}
            internal ProgressExecutionResult Save(){var r=coordinator.CreateGoal(0,Guid.NewGuid());Check(r.status=="saved","goal durable ACK");actor.trace.Add("goal-saved");return r;}
            internal ProgressExecutionResult Bind(){var r=coordinator.BindPrepared(actor.prepared.requestId,Revision(),Guid.NewGuid());Check(r.status=="bound","binding durable ACK: "+r.error);actor.trace.Add("binding-saved");return r;}
            internal void Ready(){Save();Bind();}
            internal ProgressExecutionResult Confirm(){return coordinator.Confirm(actor.prepared.requestId);}
            internal ProgressSnapshot Fresh(){return new DesktopErgonProgressStore(root,"development").Load(actor.context.scope);}
            internal void NoExecution(){Check(actor.dispatches==0&&actor.begins==0,"blocked action reached journal/dispatch");}
            internal void Pause(){Check(store.Commit(new ProgressMutation{kind="SetLifecycle",scope=actor.context.scope,goalId=actor.context.goalId,lifecycle="paused"},Revision(),Guid.NewGuid()).status=="committed","synthetic pause");}
        }
        public static void Run(string root,string mode,string only){
            var results=new List<object>();int failed=0;
            Action<string,Action> test=(id,body)=>{if(only!=""&&only!=id&&!(only=="B"&&id.StartsWith("B",StringComparison.Ordinal)))return;try{body();results.Add(new{id,status="PASS"});if(mode!="report")Console.WriteLine("PASS "+id);}catch(Exception e){failed++;results.Add(new{id,status="FAIL",error=e.Message});if(mode!="report")Console.WriteLine("FAIL "+id+": "+e.Message);}};
            test("A01",()=>{var r=new Rig(root);r.Ready();r.actor.onBegin=()=>{var saved=r.Fresh();Check(saved.revision==2&&saved.view.goals.Single().requests.Single().expectedOutput==3,"begin before saved binding");};Check(r.Confirm().status=="dispatched","happy dispatch");Check(r.actor.dispatches==1&&r.actor.trace.SequenceEqual(new[]{"goal-saved","binding-saved","lease","approval","revalidate","begin","dispatch","lease-release"}),"required order");Check(!r.Fresh().view.goals.Single().quantitySatisfied,"dispatch not quantity success");});
            test("A02",()=>{var r=new Rig(root);r.io.failWrite=true;Check(r.coordinator.CreateGoal(0,Guid.NewGuid()).status=="blocked","N01 goal failure");Check(r.coordinator.BindPrepared(r.actor.prepared.requestId,0,Guid.NewGuid()).status=="blocked","N01 prepare path after failed goal");Check(r.Confirm().status=="blocked"&&r.actor.preparedReads==0,"prepare not read before saved goal");r.NoExecution();});
            test("A03",()=>{var r=new Rig(root);r.Save();r.io.failWrite=true;Check(r.coordinator.BindPrepared(r.actor.prepared.requestId,1,Guid.NewGuid()).status=="blocked","N02 binding failure");Check(r.Confirm().status=="blocked"&&r.actor.approvals==0,"no approval after failed binding");Check(r.Fresh().view.goals.Single().requests.Length==0,"failed binding not durable");r.NoExecution();});
            test("A04",()=>{var r=new Rig(root);r.Save();Check(r.coordinator.BindPrepared(r.actor.prepared.requestId,0,Guid.NewGuid()).status=="blocked","binding CAS");r.Bind();r.Pause();Check(r.Confirm().status=="blocked","confirm revision changed");r.NoExecution();});
            test("A05",()=>{var r=new Rig(root);r.Ready();Check(r.coordinator.BindPrepared(r.actor.prepared.requestId,2,Guid.NewGuid()).status=="blocked","duplicate binding");Check(r.Confirm().status=="dispatched"&&r.Confirm().status=="blocked","one-shot confirm");Check(r.actor.dispatches==1&&r.Fresh().view.goals.Single().requests.Length==1,"dedup no extra run");});
            test("A06",()=>{foreach(var field in new[]{"environment","account","character"}){var r=new Rig(root);r.Save();if(field=="environment")r.actor.context.scope.environment="production";if(field=="account")r.actor.context.scope.accountId="other-account";if(field=="character")r.actor.context.scope.characterId="other-character";Check(r.coordinator.BindPrepared(r.actor.prepared.requestId,1,Guid.NewGuid()).status=="blocked","foreign scope "+field);r.NoExecution();}});
            test("A07",()=>{foreach(var field in new[]{"goal","plan","name","target","session","document","context"}){var r=new Rig(root);r.Ready();if(field=="goal")r.actor.context.goalId=Id();if(field=="plan")r.actor.context.sourcePlanId="other-plan";if(field=="name")r.actor.context.displayName="other-item";if(field=="target")r.actor.context.targetQuantity=5;if(field=="session")r.actor.context.sessionId=Id();if(field=="document")r.actor.context.documentEpoch++;if(field=="context")r.actor.context.contextVersion++;Check(r.Confirm().status=="blocked","stale context "+field);r.NoExecution();}});
            test("A08",()=>{var r=new Rig(root);r.Save();r.actor.prepared.craftCount=1e-50;Check(r.coordinator.BindPrepared(r.actor.prepared.requestId,1,Guid.NewGuid()).status=="blocked","strict original frozen number");r.NoExecution();});
            test("A09",()=>{var r=new Rig(root);r.Ready();var restarted=new Calls(new DesktopErgonProgressStore(r.root,"development"),r.actor,()=>r.actor.now);Check(restarted.Confirm(r.actor.prepared.requestId).status=="blocked","N03 restart cannot replay binding");Check(restarted.BindPrepared(r.actor.prepared.requestId,2,Guid.NewGuid()).status=="blocked","restart cannot remint receipt");Check(r.Fresh().view.goals.Single().requests.Length==1,"pending history kept");r.NoExecution();});
            test("A10",()=>{var r=new Rig(root);r.Ready();r.actor.failBegin=true;Check(r.Confirm().status=="dispatch-uncertain","N04 begin ACK loss protection");Check(r.Confirm().status=="blocked"&&r.actor.journal=="inflight"&&r.actor.dispatches==0,"inflight not overwritten/retried");});
            test("A11",()=>{foreach(var kind in new[]{"unknown","lease"}){var r=new Rig(root);r.Ready();if(kind=="unknown"){r.actor.unresolved=true;r.actor.journal="foreign-environment-unknown";}else r.actor.foreignLease=true;var before=r.actor.journal;Check(r.Confirm().status=="blocked"&&r.actor.journal==before,"N09 global protection unchanged");r.NoExecution();}});
            test("A12",()=>{var r=new Rig(root);r.Save();Check(r.Confirm().status=="blocked","N10 legacy nonce without binding");r.Bind();Check(r.coordinator.Confirm(Id()).status=="blocked","different nonce");r.NoExecution();});
            test("A13",()=>{foreach(var state in new[]{"unknown","epoch","pause","lease"}){var r=new Rig(root);r.Ready();r.actor.onApproval=()=>{if(state=="unknown")r.actor.unresolved=true;if(state=="epoch")r.actor.context.documentEpoch++;if(state=="pause")r.Pause();if(state=="lease")r.actor.foreignLease=true;};Check(r.Confirm().status=="blocked","N11 changed during consent "+state);r.NoExecution();}});
            test("A14",()=>{var r=new Rig(root);r.Ready();r.actor.onRevalidate=()=>r.Pause();Check(r.Confirm().status=="blocked","final store reread after native revalidation");r.NoExecution();});
            test("A15",()=>{foreach(var reason in new[]{"decline","expired","hidden"}){var r=new Rig(root);r.Ready();if(reason=="decline")r.actor.decline=true;if(reason=="expired")r.actor.now=1200;if(reason=="hidden")r.actor.allowed=false;Check(r.Confirm().status=="blocked","native final protection "+reason);Check(r.Confirm().status=="blocked","no auto retry after refusal");r.NoExecution();}});
            test("A16",()=>{var r=new Rig(root);r.Ready();File.WriteAllBytes(r.store.FilePath,new byte[]{1,2,3});Check(r.Confirm().status=="blocked","corrupt saved ACK cannot authorize");r.NoExecution();});
            test("A17",()=>{var r=new Rig(root);r.Save();var before=File.ReadAllBytes(r.store.FilePath);Check(r.coordinator.BindPrepared(r.actor.prepared.requestId,1,Guid.Empty).status=="blocked","bad operation rejected");Check(before.SequenceEqual(File.ReadAllBytes(r.store.FilePath)),"invalid operation cannot write");r.NoExecution();});
            test("A18",()=>{var r=new Rig(root);r.Ready();r.actor.prepared.outputPerCraft=2;r.actor.prepared.expectedOutput=6;Check(r.Confirm().status=="blocked","frozen recipe mismatch");r.NoExecution();});
            test("A19",()=>{foreach(var admission in new[]{"mutation","approval"}){var r=new Rig(root);r.Ready();r.actor.nullMutation=admission=="mutation";r.actor.nullApproval=admission=="approval";Check(r.Confirm().status=="blocked","null admission fails closed: "+admission);r.NoExecution();}var held=new Rig(root);held.Ready();Check(held.store.Commit(new ProgressMutation(),0,Guid.NewGuid(),null).status=="unavailable","null Store writer admission rejected");held.NoExecution();});
            test("A20",()=>{var r=new Rig(root);r.actor.context.action="gathering";r.actor.prepared.context=ProgressDomain.Clone(r.actor.context);r.actor.prepared.craftCount=null;r.actor.prepared.outputPerCraft=null;r.actor.prepared.expectedOutput=null;r.Ready();r.actor.onApproval=()=>r.actor.additionalQuantity=90;Check(r.Confirm().status=="blocked","full gathering command changed during consent");r.NoExecution();});
            test("A21",()=>{var r=new Rig(root);r.Save();r.io.published=false;r.io.failVerify=true;Check(r.coordinator.BindPrepared(r.actor.prepared.requestId,1,Guid.NewGuid()).status=="blocked","post-publication binding ACK lost");var s=r.Fresh();Check(s.health=="review-required"&&s.view.goals.Single().requests.Length==1,"published binding retained without executable receipt");Check(new Calls(new DesktopErgonProgressStore(r.root,"development"),r.actor,()=>r.actor.now).Confirm(r.actor.prepared.requestId).status=="blocked","ACK loss restart never remints receipt");r.NoExecution();});
            test("A22",()=>{var r=new Rig(root);r.Ready();using(new FileStream(r.actor.writerPath,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){Check(r.Confirm().status=="blocked","other writer admission excludes confirm");}r.NoExecution();});
            test("B01",()=>{var r=new Rig(root);r.Save();var before=File.ReadAllBytes(r.store.FilePath);using(new FileStream(r.actor.writerPath,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){var ack=r.store.Commit(new ProgressMutation{kind="SetLifecycle",scope=r.actor.context.scope,goalId=r.actor.context.goalId,lifecycle="paused"},1,Guid.NewGuid());Check(ack.status!="committed","direct Commit bypassed common writer exclusion");}Check(before.SequenceEqual(File.ReadAllBytes(r.store.FilePath)),"writer conflict changed current");});
            test("B02",()=>{var r=new Rig(root);r.Ready();r.actor.onApproval=()=>{using(new FileStream(r.actor.writerPath,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){};Check(!r.io.held,"file lock held during user approval");};Check(r.Confirm().status=="dispatched","writer lock held during user approval");});
            test("B03",()=>{var r=new Rig(root);r.Ready();r.actor.autoFinish=false;Check(r.Confirm().status=="dispatched","synthetic execution start");Check(r.actor.leaseActive&&r.actor.leaseAcquisitions==1&&r.actor.leaseReleases==0,"execution lease released before Run terminal");r.actor.Terminal();r.actor.runLease.Dispose();Check(!r.actor.leaseActive&&r.actor.leaseReleases==1,"terminal lease released exactly once");});
            test("B04",()=>{var r=new Rig(root);r.Save();var owner=new ProgressLockOwner();using(var writer=r.store.AcquireWriter(owner)){Reject(()=>r.store.AcquireWriter(owner),"same owner double writer");var timer=System.Diagnostics.Stopwatch.StartNew();Check(r.store.Commit(new ProgressMutation{kind="SetLifecycle",scope=r.actor.context.scope,goalId=r.actor.context.goalId,lifecycle="paused"},1,Guid.NewGuid()).status=="unavailable"&&timer.ElapsedMilliseconds<1500,"implicit direct Commit cannot reenter owned writer");int acquired=0;Reject(()=>ProgressExecutionLease.AcquireAsync(owner,()=>{acquired++;return Task.FromResult<IDisposable>(new Release(()=>{}));}).GetAwaiter().GetResult(),"writer to game reverse acquisition");Check(acquired==0,"reverse order acquired native resource first");using(writer.EnterStore(r.store.FilePath)){Reject(()=>writer.Dispose(),"cannot dispose writer during Store use");Reject(()=>r.store.Load(r.actor.context.scope,writer),"cannot nest same Store file lock");}var foreign=new DesktopErgonProgressStore(Path.Combine(r.root,"foreign"),"development");Check(foreign.Commit(new ProgressMutation(),0,Guid.NewGuid(),writer).status=="unavailable","foreign Store admission rejected");}using(r.store.AcquireWriter(owner)){};});
            test("B05",()=>{var r=new Rig(root);r.Save();var before=File.ReadAllBytes(r.store.FilePath);using(r.store.AcquireWriter(new ProgressLockOwner()))foreach(var kind in new[]{"CreateGoal","BindPreparedRequest","ConfirmQuantity","CorrectQuantity","SetLifecycle","DetachPlan","Recover","ObserveNativeTerminal"}){var result=r.store.Commit(new ProgressMutation{kind=kind,scope=r.actor.context.scope,goalId=r.actor.context.goalId},1,Guid.NewGuid());Check(result.status=="unavailable"&&result.error=="writer-unavailable","mutation escaped common guard: "+kind);}Check(before.SequenceEqual(File.ReadAllBytes(r.store.FilePath)),"guarded mutations changed bytes");});
            test("B06",()=>{var r=new Rig(root);r.Ready();new Pump().Run(async ()=>{r.actor.approvalWait=new TaskCompletionSource<bool>();var pending=r.coordinator.native.ConfirmAsync(r.actor.prepared.requestId);while(r.actor.approvals==0)await Task.Delay(1);Check(!pending.IsCompleted&&r.actor.leaseActive&&!r.io.held,"approval wait ownership");using(r.store.AcquireWriter(new ProgressLockOwner())){};r.actor.approvalWait.SetResult(true);Check((await pending).status=="dispatched"&&r.actor.leaseReleases==1,"UI context deadlock or leaked resource");});});
            test("B07",()=>{foreach(var change in new[]{"character","nonce","revision","expiry"}){var r=new Rig(root);r.Ready();r.actor.approvalWait=new TaskCompletionSource<bool>();var pending=r.coordinator.native.ConfirmAsync(r.actor.prepared.requestId);Wait(()=>r.actor.approvals==1,"approval started");if(change=="character")r.actor.context.scope.characterId="changed";if(change=="nonce")r.actor.prepared.requestId=Id();if(change=="revision")r.Pause();if(change=="expiry")r.actor.now=1200;r.actor.approvalWait.SetResult(true);Check(pending.GetAwaiter().GetResult().status=="blocked","async changed "+change);r.NoExecution();Check(r.actor.leaseAcquisitions==1&&r.actor.leaseReleases==1,"async refusal lease cleanup");}});
            test("B08",()=>{var r=new Rig(root);r.Ready();r.actor.revalidateWait=new TaskCompletionSource<bool>();var pending=r.coordinator.native.ConfirmAsync(r.actor.prepared.requestId);Wait(()=>r.actor.approvals==1,"revalidate stage");r.actor.context.documentEpoch++;r.actor.revalidateWait.SetResult(true);Check(pending.GetAwaiter().GetResult().status=="blocked"&&r.actor.leaseReleases==1,"post-await epoch gate");r.NoExecution();});
            test("B09",()=>{foreach(var failure in new[]{"decline","exception"}){var r=new Rig(root);r.Ready();if(failure=="decline")r.actor.decline=true;else r.actor.onApproval=()=>{throw new IOException("synthetic-user-prompt-failure");};Check(r.Confirm().status=="blocked"&&r.actor.leaseAcquisitions==1&&r.actor.leaseReleases==1,"prompt refusal leaked lease");using(new FileStream(r.actor.writerPath+".game",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){};r.NoExecution();}});
            test("B10",()=>{var r=new Rig(root);r.Ready();r.actor.autoFinish=false;Check(r.Confirm().status=="dispatched","start");Reject(()=>r.actor.lastOffer.Claim(),"lease claimed twice");bool busy=false;try{using(new FileStream(r.actor.writerPath+".game",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){};}catch(IOException){busy=true;}Check(busy&&r.actor.leaseAcquisitions==1,"global lease released before terminal");r.actor.Terminal();});
            test("B11",()=>{var r=new Rig(root);r.Ready();r.actor.autoFinish=false;r.actor.throwAfterClaim=true;Check(r.Confirm().status=="dispatch-uncertain"&&r.actor.leaseActive&&r.actor.leaseReleases==0,"claimed lease reclaimed on uncertain start");Check(r.Confirm().status=="blocked"&&r.actor.leaseAcquisitions==1&&r.actor.journal=="inflight","uncertain start automatically replayed");r.actor.Terminal();Check(r.actor.leaseReleases==1,"run release");});
            test("B12",()=>{var r=new Rig(root);r.Ready();r.actor.noClaim=true;Check(r.Confirm().status=="dispatch-uncertain"&&!r.actor.leaseActive&&r.actor.leaseReleases==1,"unclaimed start lease cleanup");Check(r.Confirm().status=="blocked"&&r.actor.dispatches==0&&r.actor.journal=="inflight","unclaimed start retried/cleared");});
            test("B13",()=>{var r=new Rig(root);r.Ready();r.actor.autoFinish=false;r.Confirm();r.actor.journal="completed";using(var writer=r.store.AcquireWriter(r.actor.runLease.Owner)){var p=r.actor.prepared;var ack=r.store.Commit(new ProgressMutation{kind="ObserveNativeTerminal",scope=p.context.scope,goalId=p.context.goalId,requestId=p.requestId,evidence=new NativeTerminalEvidence{scope=p.context.scope,goalId=p.context.goalId,requestId=p.requestId,action="crafting",displayName=p.context.displayName,craftCount=3,outputPerCraft=1,expectedOutput=3,outcome="completed",startedAt=1000,observedAt=1100,verifierVersion=1,rowDigest=new string('a',64)}},2,Guid.NewGuid(),writer);Check(ack.status=="committed"&&r.actor.leaseActive,"terminal writer order/lease");}r.actor.Terminal();Check(r.Fresh().view.goals.Single().requests.Single().terminalOutcome=="completed"&&r.actor.leaseReleases==1,"terminal saved before release");});
            test("B14",()=>{var r=new Rig(root);r.Ready();r.actor.autoFinish=false;r.Confirm();r.actor.journal="completed";var before=File.ReadAllBytes(r.store.FilePath);r.io.failWrite=true;Check(r.store.Commit(new ProgressMutation{kind="SetLifecycle",scope=r.actor.context.scope,goalId=r.actor.context.goalId,lifecycle="paused"},2,Guid.NewGuid()).status=="unavailable","failed progress save ACK");Check(r.actor.journal=="completed"&&r.actor.leaseActive&&before.SequenceEqual(File.ReadAllBytes(r.store.FilePath))&&r.Fresh().view.goals.Single().confirmedQuantity==0,"progress failure changed native/quantity");r.actor.Terminal();Check(r.Confirm().status=="blocked","failed save retried consumption");});
            test("B15",()=>{var r=new Rig(root);r.Save();using(var a=Child(r.root,r.actor.context.goalId,"a"))using(var b=Child(r.root,r.actor.context.goalId,"b")){try{Wait(()=>File.Exists(Path.Combine(r.root,"a.ready"))&&File.Exists(Path.Combine(r.root,"b.ready")),"workers ready");File.WriteAllText(Path.Combine(r.root,"go"),"go");EndChild(a);EndChild(b);var workerResults=new[]{a.StandardOutput.ReadToEnd().Trim(),b.StandardOutput.ReadToEnd().Trim()};Check(workerResults.Count(x=>x=="committed")==1&&workerResults.Count(x=>x=="conflict")==1&&r.Fresh().revision==2,"two-process writer/CAS lost update");}finally{if(!a.HasExited)a.Kill();if(!b.HasExited)b.Kill();}}});
            test("B16",()=>{var r=new Rig(root);r.Save();var before=File.ReadAllBytes(r.store.FilePath);using(var p=Child(r.root,r.actor.context.goalId,"hold")){try{Wait(()=>File.Exists(Path.Combine(r.root,"held")),"child writer held");Check(r.store.Commit(new ProgressMutation{kind="SetLifecycle",scope=r.actor.context.scope,goalId=r.actor.context.goalId,lifecycle="paused"},1,Guid.NewGuid()).status=="unavailable","cross-process writer bypass");Check(before.SequenceEqual(File.ReadAllBytes(r.store.FilePath)),"cross-process denied write changed current");File.WriteAllText(Path.Combine(r.root,"release"),"release");EndChild(p);}finally{if(!p.HasExited)p.Kill();}}});
            test("B17",()=>{var r=new Rig(root);r.Ready();Check(r.coordinator.native.Confirm(r.actor.prepared.requestId).status=="blocked"&&r.actor.leaseAcquisitions==0,"legacy synchronous confirm bypassed async gate");r.NoExecution();});
            test("B18",()=>{foreach(var operation in new[]{"create","bind","confirm"}){var r=new Rig(root);if(operation!="create")r.Save();if(operation=="confirm")r.Bind();r.actor.mutationWait=new TaskCompletionSource<bool>();var pending=operation=="create"?r.coordinator.native.CreateGoalAsync(0,Guid.NewGuid()):operation=="bind"?r.coordinator.native.BindPreparedAsync(r.actor.prepared.requestId,1,Guid.NewGuid()):r.coordinator.native.ConfirmAsync(r.actor.prepared.requestId);Check(!pending.IsCompleted,"mutation acquisition must await");r.actor.context.scope.characterId="changed-during-mutation-wait";r.actor.mutationWait.SetResult(true);Check(pending.GetAwaiter().GetResult().status=="blocked","context changed during mutation admission: "+operation);r.NoExecution();}});
            test("B19",()=>{var r=new Rig(root);r.Save();var before=File.ReadAllBytes(r.store.FilePath);var owner=new ProgressLockOwner();using(var held=new FileStream(r.store.FilePath+".writers.lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))using(var forged=new ProgressWriterAdmission(r.store.FilePath+".writers.lock",owner,owner.Enter(ProgressLockOwner.Writer),new Release(()=>{}),()=>{})){var result=r.store.Commit(new ProgressMutation{kind="SetLifecycle",scope=r.actor.context.scope,goalId=r.actor.context.goalId,lifecycle="paused"},1,Guid.NewGuid(),forged);Check(result.status=="unavailable","forged admission bypassed OS writer");Check(before.SequenceEqual(File.ReadAllBytes(r.store.FilePath)),"forged admission changed ciphertext");}});
            test("B20",()=>{var r=new Rig(root);r.Save();int releases=0;var owner=new ProgressLockOwner();var lease=ProgressExecutionLease.AcquireAsync(owner,()=>Task.FromResult<IDisposable>(new Release(()=>{releases++;throw new IOException("synthetic-release-after-close");}))).GetAwaiter().GetResult();try{lease.Dispose();}catch(IOException){}try{lease.Dispose();}catch(IOException){}Check(releases==1,"throwing raw lease disposed more than once");using(r.store.AcquireWriter(owner)){};});
            if(mode=="report")Console.WriteLine(ProgressDomain.Serialize(new{failed,results}));
            if(failed>0)throw new Exception("integration failures: "+failed);
        }
    }
